+import type {EventEmitter} from 'node:events';
+import unhandle from './core/utils/unhandle.js';
+
+export type Outcome = 'response' | 'error';
+
+/**
+Call `callback` once with the name and first payload of whichever of `response` or `error` the emitter fires first, then remove both listeners.
+
+@returns A function that removes both listeners without calling `callback`.
+*/
+export function watchOutcome(emitter: EventEmitter, callback: (event: Outcome, payload: unknown) => void): () => void {
+	const handlers = unhandle();
+	let settled = false;
+
+	const settle = (event: Outcome, payload: unknown) => {
+		if (settled) {
+			return;
+		}
+
+		settled = true;
+		handlers.unhandleAll();
+		callback(event, payload);
+	};
+
+	handlers.once(emitter, 'response', (payload: unknown) => {
+		settle('response', payload);
+	});
+	handlers.once(emitter, 'error', (payload: unknown) => {
+		settle('error', payload);
+	});
+
+	return () => {
+		settled = true;
+		handlers.unhandleAll();
+	};
+}
diff --git a/test/first-outcome.ts b/test/first-outcome.ts
new file mode 100644
index 0000000..a97d855
--- /dev/null
+++ b/test/first-outcome.ts
@@ -0,0 +1,51 @@
+import {EventEmitter} from 'node:events';
+import test from 'ava';
+import {watchOutcome} from '../source/first-outcome.js';
+
+test('calls back once with the first response and removes both listeners', t => {
+	const emitter = new EventEmitter();
+	const calls: unknown[][] = [];
+	watchOutcome(emitter, (...arguments_) => calls.push(arguments_));
+
+	emitter.emit('response', 'first', 'extra');
+	emitter.emit('response', 'second');
+	emitter.on('error', () => {});
+	emitter.emit('error', new Error('late'));
+
+	t.deepEqual(calls, [['response', 'first']]);
+	t.is(emitter.listenerCount('response'), 0);
+	t.is(emitter.listenerCount('error'), 1);
+});
+
+test('calls back once with the first error and removes both listeners', t => {
+	const emitter = new EventEmitter();
+	const error = new Error('boom');
+	const calls: unknown[][] = [];
+	watchOutcome(emitter, (...arguments_) => calls.push(arguments_));
+
+	emitter.emit('error', error);
+	emitter.emit('response', 'late');
+
+	t.deepEqual(calls, [['error', error]]);
+	t.is(emitter.listenerCount('response'), 0);
+	t.is(emitter.listenerCount('error'), 0);
+});
+
+test('cancelling removes only its own listeners and never calls back', t => {
+	const emitter = new EventEmitter();
+	const unrelated = () => {};
+	emitter.on('response', unrelated);
+	emitter.on('error', unrelated);
+	let called = false;
+	const cancel = watchOutcome(emitter, () => {
+		called = true;
+	});
+
+	cancel();
+	emitter.emit('response', 'value');
+	emitter.emit('error', new Error('boom'));
+
+	t.false(called);
+	t.deepEqual(emitter.listeners('response'), [unrelated]);
+	t.deepEqual(emitter.listeners('error'), [unrelated]);
+});
